1	// Package bench is the forgemark benchmark engine: it drives real git
2	// push/clone operations against one target forge and reports per-level
3	// results. The CLI (cmd/forgemark) and the web server (internal/server) are
4	// both thin frontends over Runner.
5	package bench
6	
7	import (
8		"errors"
9		"fmt"
10		"net/url"
11		"strconv"
12		"strings"
13		"time"
14	
15		"github.com/go-git/go-git/v6/plumbing"
16	)
17	
18	// Target is one forge to benchmark: where to connect and how to authenticate.
19	// Supplying TokenURL or Jurisdiction selects the entiredb path (jurisdiction
20	// token exchange + node discovery); they mean nothing to any other forge, so
21	// their presence is the signal — no separate target-kind field.
22	type Target struct {
23		Name      string   // display label; empty defaults to the remote base URL
24		Remote    string   // base URL of the forge, e.g. https://gitlab.com
25		Repos     []string // repo paths appended to Remote verbatim
26		User      string   // basic-auth username (default x-access-token; token forges ignore it)
27		Secret    string   // credential secret (forge token, or the entiredb subject token). Never serialized.
28		Insecure  bool     // skip TLS verification
29		ObjectFmt string   // "auto" | "sha1" | "sha256"
30	
31		// entiredb
32		TokenURL     string // core /oauth/token endpoint (selects entiredb)
33		Jurisdiction string // jurisdiction audience host, bare origin (selects entiredb)
34		ClientID     string // public OAuth client id; empty defaults to entire-cli
35	}
36	
37	// Workload is the target-independent shape of a run: strategy, sweep, and
38	// commit content. One Workload is shared by every target of a comparison run.
39	type Workload struct {
40		RunID        string
41		Strategy     string // branch | repo | clone | session
42		BranchPrefix string
43		Concurrency  []int
44		Duration     time.Duration
45		Warmup       time.Duration
46		Commit       CommitConfig
47	
48		// session/clone strategies
49		SessionCommits int
50		CloneDepth     int
51		BaseRef        string
52	}
53	
54	// Validate applies the target-independent checks that parseFlags used to do,
55	// so the server rejects a bad workload with the same errors the CLI reports.
56	func (w Workload) Validate() error {
57		switch w.Strategy {
58		case "branch", "repo", "clone", "session":
59		default:
60			return fmt.Errorf("invalid -strategy %q (branch|repo|clone|session)", w.Strategy)
61		}
62		if w.Strategy == "session" && w.SessionCommits < 1 {
63			return errors.New("-session-commits must be >= 1")
64		}
65		if len(w.Concurrency) == 0 {
66			return errors.New("no concurrency levels")
67		}
68		for _, n := range w.Concurrency {
69			if n < 1 {
70				return fmt.Errorf("invalid concurrency %d", n)
71			}
72		}
73		if w.Duration <= 0 {
74			return errors.New("-duration must be > 0")
75		}
76		if w.Warmup < 0 {
77			return errors.New("-warmup must be >= 0")
78		}
79		if w.Strategy != "clone" {
80			if w.Commit.FilesMin < 1 {
81				return errors.New("-files-min must be >= 1 (a commit needs a change to push)")
82			}
83			if w.Commit.FilesMax < w.Commit.FilesMin {
84				return errors.New("-files-max < -files-min")
85			}
86			if w.Commit.FileSize < 1 {
87				return errors.New("-file-size must be >= 1 (empty blobs reproduce → ErrEmptyCommit)")
88			}
89		}
90		// Validate the assembled ref, not the prefix alone: validity is context-dependent
91		// (a trailing "/" or bare word is fine mid-ref, invalid standalone). c/a are arbitrary —
92		// only the prefix can invalidate it — so this one parse-time check covers the whole sweep.
93		runID := w.RunID
94		if runID == "" {
95			runID = "fmX"
96		}
97		if err := plumbing.ReferenceName(DestRef(w.BranchPrefix, runID, 1, 0)).Validate(); err != nil {
98			return fmt.Errorf("invalid -branch-prefix %q: %w", w.BranchPrefix, err)
99		}
100		return nil
101	}
102	
103	// CommitDesc describes the commit content shape, e.g. "1-10 x 2048B".
104	func (w Workload) CommitDesc() string {
105		return fmt.Sprintf("%d-%d x %dB", w.Commit.FilesMin, w.Commit.FilesMax, w.Commit.FileSize)
106	}
107	
108	// NewRunID returns a fresh run identifier. Nanosecond resolution so two runs
109	// started back-to-back (a server restarting a sweep) can't collide.
110	func NewRunID() string {
111		return "fm" + strconv.FormatInt(time.Now().UnixNano(), 36)
112	}
113	
114	// DestRef builds an agent's destination branch ref, prepending branchPrefix
115	// verbatim before the run ID. Empty prefix reproduces the default name.
116	func DestRef(branchPrefix, runID string, c, i int) string {
117		return fmt.Sprintf("refs/heads/%s%s-c%d-a%d", branchPrefix, runID, c, i)
118	}
119	
120	// IsGitHubDotCom reports whether remote points at github.com (so the abuse
121	// warning + sha1 constraint apply). Any other host — GHES, GitLab, Gitea — is
122	// just a generic forge.
123	func IsGitHubDotCom(remote string) bool {
124		u, err := url.Parse(remote)
125		if err != nil {
126			return false
127		}
128		return strings.EqualFold(u.Hostname(), "github.com")
129	}
