1	// EventSource wrapper for a run's event stream. The browser reconnects
2	// automatically and re-sends Last-Event-ID; the server replays anything
3	// missed, so handlers can treat the stream as gapless and in-order. The
4	// caller closes it on run_done — after that the stream only ever replays.
5	
6	export function openRunStream(runId, handlers) {
7	  const es = new EventSource(`/api/runs/${encodeURIComponent(runId)}/events`);
8	  for (const [name, fn] of Object.entries(handlers)) {
9	    es.addEventListener(name, (ev) => fn(JSON.parse(ev.data)));
10	  }
11	  return es;
12	}
13

1	// Tiny DOM builder: h('div', {class: 'card', onclick: fn}, child, …).
2	// Strings become text nodes; arrays flatten; null/undefined are skipped.
3	
4	export function h(tag, attrs = {}, ...children) {
5	  const el = document.createElement(tag);
6	  for (const [k, v] of Object.entries(attrs || {})) {
7	    if (v == null) continue;
8	    if (k.startsWith('on') && typeof v === 'function') {
9	      el.addEventListener(k.slice(2), v);
10	    } else if (k === 'dataset') {
11	      Object.assign(el.dataset, v);
12	    } else if (k === 'style' && typeof v === 'object') {
13	      for (const [prop, val] of Object.entries(v)) {
14	        if (prop.startsWith('--')) el.style.setProperty(prop, val);
15	        else el.style[prop] = val;
16	      }
17	    } else if (k in el && k !== 'type' && k !== 'value') {
18	      try { el[k] = v; } catch { el.setAttribute(k, v); }
19	    } else {
20	      el.setAttribute(k, v);
21	    }
22	  }
23	  append(el, children);
24	  return el;
25	}
26	
27	function append(el, kids) {
28	  for (const k of kids) {
29	    if (k == null) continue;
30	    if (Array.isArray(k)) { append(el, k); continue; }
31	    el.append(k.nodeType ? k : document.createTextNode(String(k)));
32	  }
33	}
