1	// Thin fetch wrappers over the forgemark API. All errors surface as thrown
2	// Error objects carrying the server's message.
3	
4	async function req(method, path, body) {
5	  const res = await fetch(path, {
6	    method,
7	    headers: body ? { 'Content-Type': 'application/json' } : undefined,
8	    body: body ? JSON.stringify(body) : undefined,
9	  });
10	  const text = await res.text();
11	  let data = null;
12	  try { data = text ? JSON.parse(text) : null; } catch { /* non-JSON error body */ }
13	  if (!res.ok) {
14	    throw new Error((data && data.error) || `${res.status} ${res.statusText}`);
15	  }
16	  return data;
17	}
18	
19	export const api = {
20	  startRun: (spec) => req('POST', '/api/runs', spec),
21	  listRuns: () => req('GET', '/api/runs'),
22	  getRun: (id) => req('GET', `/api/runs/${encodeURIComponent(id)}`),
23	  cancelRun: (id) => req('POST', `/api/runs/${encodeURIComponent(id)}/cancel`),
24	  history: () => req('GET', '/api/history'),
25	  historyDoc: (file) => req('GET', `/api/history/${encodeURIComponent(file)}`),
26	};
