1	// Package server is the forgemark web GUI: a localhost HTTP server that runs
2	// benchmark sweeps (one or many targets, level-aligned) over internal/bench
3	// and streams live per-second stats to an embedded single-page UI over SSE.
4	package server
5	
6	import (
7		"context"
8		"embed"
9		"encoding/json"
10		"errors"
11		"fmt"
12		"io/fs"
13		"net"
14		"net/http"
15		"net/url"
16		"time"
17	
18		"github.com/entireio/forgemark/internal/results"
19	)
20	
21	//go:embed static
22	var staticFiles embed.FS
23	
24	type Server struct {
25		addr string
26		mgr  *RunManager
27		mux  *http.ServeMux
28	}
29	
30	// New builds the server. resultsDir is where finished runs are persisted and
31	// where history is read from (shared with the CLI's results/ by default).
32	func New(addr, resultsDir string) *Server {
33		s := &Server{addr: addr, mgr: newRunManager(resultsDir), mux: http.NewServeMux()}
34	
35		staticRoot, err := fs.Sub(staticFiles, "static")
36		if err != nil {
37			panic("embedded static assets missing: " + err.Error()) // build-time invariant
38		}
39		s.mux.Handle("GET /", http.FileServerFS(staticRoot))
40	
41		s.mux.HandleFunc("POST /api/runs", s.requireLocalOrigin(s.handleStartRun))
42		s.mux.HandleFunc("GET /api/runs", s.handleListRuns)
43		s.mux.HandleFunc("GET /api/runs/{id}", s.handleGetRun)
44		s.mux.HandleFunc("POST /api/runs/{id}/cancel", s.requireLocalOrigin(s.handleCancelRun))
45		s.mux.HandleFunc("GET /api/runs/{id}/events", s.handleRunEvents)
46		s.mux.HandleFunc("GET /api/history", s.handleHistory)
47		s.mux.HandleFunc("GET /api/history/{file}", s.handleHistoryDoc)
48		return s
49	}
50	
51	// Handler exposes the mux for httptest.
52	func (s *Server) Handler() http.Handler { return s.mux }
53	
54	// ListenAndServe blocks until ctx is cancelled or the listener fails.
55	func (s *Server) ListenAndServe(ctx context.Context) error {
56		srv := &http.Server{Addr: s.addr, Handler: s.mux, ReadHeaderTimeout: 10 * time.Second}
57		errc := make(chan error, 1)
58		go func() { errc <- srv.ListenAndServe() }()
59		select {
60		case err := <-errc:
61			return err
62		case <-ctx.Done():
63			shutCtx, cancel := context.WithTimeout(context.Background(), 3*time.Second)
64			defer cancel()
65			_ = srv.Shutdown(shutCtx)
66			return nil
67		}
68	}
69	
70	// requireLocalOrigin guards mutating endpoints against DNS-rebinding/CSRF: the
71	// UI pastes credentials, so a hostile web page must not be able to drive this
72	// API. Browsers always send Origin on cross-origin POSTs; a request with no
73	// Origin header is curl or same-origin-old-browser, which is fine for a
74	// loopback tool.
75	func (s *Server) requireLocalOrigin(next http.HandlerFunc) http.HandlerFunc {
76		return func(w http.ResponseWriter, r *http.Request) {
77			if origin := r.Header.Get("Origin"); origin != "" {
78				u, err := url.Parse(origin)
79				if err != nil || !isLoopbackHost(u.Hostname()) {
80					http.Error(w, "forbidden origin", http.StatusForbidden)
81					return
82				}
83			}
84			next(w, r)
85		}
86	}
87	
88	func isLoopbackHost(host string) bool {
89		if host == "localhost" {
90			return true
91		}
92		ip := net.ParseIP(host)
93		return ip != nil && ip.IsLoopback()
94	}
95	
96	func (s *Server) handleStartRun(w http.ResponseWriter, r *http.Request) {
97		var req startRequest
98		dec := json.NewDecoder(http.MaxBytesReader(w, r.Body, 1<<20))
99		dec.DisallowUnknownFields()
100		if err := dec.Decode(&req); err != nil {
101			httpError(w, http.StatusBadRequest, fmt.Sprintf("bad request body: %v", err))
102			return
103		}
104		run, warnings, err := s.mgr.start(req)
105		if err != nil {
106			code := http.StatusBadRequest
107			if errors.Is(err, errRunActive) {
108				code = http.StatusConflict
109			}
110			httpError(w, code, err.Error())
111			return
112		}
113		writeJSON(w, http.StatusCreated, map[string]any{"id": run.ID, "warnings": warnings})
114	}
115	
116	func (s *Server) handleListRuns(w http.ResponseWriter, _ *http.Request) {
117		runs := s.mgr.list()
118		out := make([]runStatus, len(runs))
119		for i, r := range runs {
120			out[i] = r.status()
121		}
122		writeJSON(w, http.StatusOK, out)
123	}
124	
125	func (s *Server) handleGetRun(w http.ResponseWriter, r *http.Request) {
126		run := s.mgr.get(r.PathValue("id"))
127		if run == nil {
128			httpError(w, http.StatusNotFound, "no such run")
129			return
130		}
131		writeJSON(w, http.StatusOK, run.status())
132	}
133	
134	func (s *Server) handleCancelRun(w http.ResponseWriter, r *http.Request) {
135		run := s.mgr.get(r.PathValue("id"))
136		if run == nil {
137			httpError(w, http.StatusNotFound, "no such run")
138			return
139		}
140		run.cancel()
141		writeJSON(w, http.StatusOK, map[string]any{"id": run.ID, "cancelling": true})
142	}
143	
144	func (s *Server) handleRunEvents(w http.ResponseWriter, r *http.Request) {
145		run := s.mgr.get(r.PathValue("id"))
146		if run == nil {
147			httpError(w, http.StatusNotFound, "no such run")
148			return
149		}
150		serveSSE(w, r, run.log)
151	}
152	
153	func (s *Server) handleHistory(w http.ResponseWriter, _ *http.Request) {
154		list, err := results.List(s.mgr.resultsDir)
155		if err != nil {
156			httpError(w, http.StatusInternalServerError, err.Error())
157			return
158		}
159		writeJSON(w, http.StatusOK, list)
160	}
161	
162	func (s *Server) handleHistoryDoc(w http.ResponseWriter, r *http.Request) {
163		doc, err := results.Load(s.mgr.resultsDir, r.PathValue("file"))
164		switch {
165		case errors.Is(err, results.ErrNotFound):
166			httpError(w, http.StatusNotFound, "no such result file")
167		case err != nil:
168			httpError(w, http.StatusBadRequest, err.Error())
169		default:
170			writeJSON(w, http.StatusOK, doc)
171		}
172	}
173	
174	func writeJSON(w http.ResponseWriter, code int, v any) {
175		w.Header().Set("Content-Type", "application/json")
176		w.WriteHeader(code)
177		_ = json.NewEncoder(w).Encode(v)
178	}
179	
180	func httpError(w http.ResponseWriter, code int, msg string) {
181		writeJSON(w, code, map[string]string{"error": msg})
182	}
183

1	// New-run form: one workload, 1..8 targets. Secrets go straight into the POST
