11	
12	// maxBufferedEvents caps a run's replayable event log. At ~1 bucket event per
13	// second this is over a day of run time — a backstop, not a working limit.
14	const maxBufferedEvents = 100_000
15	
16	// event is one serialized SSE frame: a 1-based sequence number (the SSE id,
17	// which browsers echo back as Last-Event-ID on reconnect), a type, and its
18	// marshaled JSON payload.
19	type event struct {
20		seq  int64
21		name string
22		data []byte
23	}
24	
25	// eventLog is a run's append-only event history plus live fanout. Every event
26	// is retained (bounded by maxBufferedEvents), so a subscriber at any point —
27	// first open, late join, browser reconnect — is handled the same way: replay
28	// everything after its Last-Event-ID, then stream. That makes dropping a slow
29	// subscriber lossless: it reconnects and replays what it missed.
30	type eventLog struct {
31		mu     sync.Mutex
32		events []event
33		subs   map[chan event]struct{}
34		closed bool
35	}
36	
37	func newEventLog() *eventLog {
38		return &eventLog{subs: make(map[chan event]struct{})}
39	}
40	
41	// emit marshals v, appends the event, and fans it out. A subscriber whose
42	// buffer is full is dropped (its channel closed) rather than blocking the
43	// coordinator; the SSE handler ends that response and the browser reconnects
44	// into a replay.
45	func (l *eventLog) emit(name string, v any) {
46		data, err := json.Marshal(v)
47		if err != nil {
48			// A marshal failure is a programming error in an event payload; surface
49			// it in-band rather than silently dropping the event.
50			data = fmt.Appendf(nil, `{"error":"marshal: %s"}`, err)
51		}
52		l.mu.Lock()
53		defer l.mu.Unlock()
54		if l.closed || len(l.events) >= maxBufferedEvents {
55			return
56		}
57		e := event{seq: int64(len(l.events)) + 1, name: name, data: data}
58		l.events = append(l.events, e)
59		for ch := range l.subs {
60			select {
61			case ch <- e:
62			default:
63				delete(l.subs, ch)
64				close(ch)
65			}
66		}
67	}
68	
69	// subscribe returns the replay of every event after seq `after`, plus a live
70	// channel (nil if the log is closed — the replay then already ends in the
71	// terminal event) and a cancel func.
72	func (l *eventLog) subscribe(after int64) ([]event, chan event, func()) {
73		l.mu.Lock()
74		defer l.mu.Unlock()
75		var replay []event
76		if after < int64(len(l.events)) {
77			replay = append(replay, l.events[after:]...)
78		}
79		if l.closed {
80			return replay, nil, func() {}
81		}
82		ch := make(chan event, 256)
83		l.subs[ch] = struct{}{}
84		cancel := func() {
85			l.mu.Lock()
86			defer l.mu.Unlock()
87			if _, ok := l.subs[ch]; ok {
88				delete(l.subs, ch)
89				close(ch)
90			}
91		}
92		return replay, ch, cancel
93	}
94	
95	// close ends the log after the terminal event has been emitted: live
96	// subscribers are closed out (their replay already delivered everything) and
97	// future subscribers get replay-only.
98	func (l *eventLog) close() {
99		l.mu.Lock()
100		defer l.mu.Unlock()
101		l.closed = true
102		for ch := range l.subs {
103			delete(l.subs, ch)
104			close(ch)
105		}
106	}
107	
108	// serveSSE streams an eventLog as a Server-Sent-Events response: replay from
109	// the client's Last-Event-ID (or 0), then live events, with a comment
110	// heartbeat so proxies and the browser keep the connection alive.
111	func serveSSE(w http.ResponseWriter, r *http.Request, l *eventLog) {
112		fl, ok := w.(http.Flusher)
113		if !ok {
114			http.Error(w, "streaming unsupported", http.StatusInternalServerError)
115			return
116		}
117		var after int64
118		if v := r.Header.Get("Last-Event-ID"); v != "" {
119			after, _ = strconv.ParseInt(v, 10, 64)
120		}
121	
122		w.Header().Set("Content-Type", "text/event-stream")
123		w.Header().Set("Cache-Control", "no-cache")
124		w.Header().Set("X-Accel-Buffering", "no")
125		w.WriteHeader(http.StatusOK)
126	
127		replay, ch, cancel := l.subscribe(after)
128		defer cancel()
129		for _, e := range replay {
130			writeSSE(w, e)
131		}
132		fl.Flush()
133		if ch == nil {
134			return // run already finished; the replay ended in run_done
135		}
136	
137		heartbeat := time.NewTicker(15 * time.Second)
138		defer heartbeat.Stop()
139		for {
140			select {
141			case e, ok := <-ch:
142				if !ok {
143					return // log closed (run finished) or we were dropped as slow
144				}
145				writeSSE(w, e)
146				fl.Flush()
147			case <-heartbeat.C:
148				fmt.Fprint(w, ": ping\n\n")
149				fl.Flush()
150			case <-r.Context().Done():
151				return
152			}
153		}
154	}
155	
156	func writeSSE(w http.ResponseWriter, e event) {
157		fmt.Fprintf(w, "id: %d\nevent: %s\ndata: %s\n\n", e.seq, e.name, e.data)
158	}
