27	// Doc is a stored run. Exactly one of the two shapes is populated on disk;
28	// Load always returns the Targets shape.
29	type Doc struct {
30		Format   int    `json:"format,omitempty"` // 2; absent/0 = legacy CLI doc
31		RunID    string `json:"run_id"`
32		Strategy string `json:"strategy"`
33		Duration string `json:"duration"`
34		Warmup   string `json:"warmup"`
35		Commit   string `json:"commit"`
36	
37		// format 2
38		State   string         `json:"state,omitempty"` // done | cancelled | failed
39		Targets []TargetResult `json:"targets,omitempty"`
40	
41		// format 1 (legacy CLI)
42		Target    string              `json:"target,omitempty"`
43		RepoCount int                 `json:"repo_count,omitempty"`
44		Levels    []bench.LevelResult `json:"levels,omitempty"`
45	}
46	
47	// TargetResult is one target's outcome within a run.
48	type TargetResult struct {
49		Name   string              `json:"name"`
50		Label  string              `json:"label,omitempty"`
51		Error  string              `json:"error,omitempty"` // fatal target error, if it died
52		Levels []bench.LevelResult `json:"levels"`
53		Series []SeriesPoint       `json:"series,omitempty"` // 1s live buckets, for re-rendering
54	}
55	
56	// SeriesPoint is one second of one target's live stats.
57	type SeriesPoint struct {
58		T     int64   `json:"t"`
59		Level int     `json:"level"`
60		OK    int     `json:"ok"`
61		CAS   int     `json:"cas"`
62		Err   int     `json:"err"`
63		P50   float64 `json:"p50_ms"`
64		P95   float64 `json:"p95_ms"`
65		P99   float64 `json:"p99_ms"`
66	}
67	
68	// Summary is one history listing entry.
69	type Summary struct {
70		File     string    `json:"file"`
71		RunID    string    `json:"run_id"`
72		Strategy string    `json:"strategy"`
73		State    string    `json:"state,omitempty"`
74		Targets  []string  `json:"targets"`
75		Levels   int       `json:"levels"`
76		ModTime  time.Time `json:"mtime"`
77	}
78	
79	// ErrNotFound reports a missing result file.
80	var ErrNotFound = errors.New("result file not found")
81	
82	// validFile is the only filename shape this package will touch. It doubles as
83	// the path-traversal guard for filenames arriving from HTTP.
84	var validFile = regexp.MustCompile(`^forgemark-[A-Za-z0-9._-]+\.json$`)
85	
86	// Write stores a format-2 doc as <dir>/<file>, creating dir if needed.
87	func Write(dir, file string, doc Doc) error {
88		if !validFile.MatchString(file) {
89			return fmt.Errorf("invalid result filename %q", file)
90		}
91		if err := os.MkdirAll(dir, 0o750); err != nil {
92			return fmt.Errorf("mkdir %s: %w", dir, err)
93		}
94		b, err := json.MarshalIndent(doc, "", "  ")
95		if err != nil {
96			return fmt.Errorf("marshal results: %w", err)
97		}
98		if err := os.WriteFile(filepath.Join(dir, file), b, 0o600); err != nil {
99			return fmt.Errorf("write results: %w", err)
100		}
101		return nil
102	}
103	
104	// List summarizes every parseable result doc in dir, newest first. Unparseable
105	// files are skipped, not fatal — the directory is shared and hand-editable.
106	func List(dir string) ([]Summary, error) {
107		entries, err := os.ReadDir(dir)
108		if errors.Is(err, os.ErrNotExist) {
109			return []Summary{}, nil
110		}
111		if err != nil {
112			return nil, err
113		}
114		out := []Summary{}
115		for _, e := range entries {
116			if e.IsDir() || !validFile.MatchString(e.Name()) {
117				continue
118			}
119			doc, err := Load(dir, e.Name())
120			if err != nil {
121				continue
122			}
123			info, err := e.Info()
124			if err != nil {
125				continue
126			}
127			s := Summary{
128				File: e.Name(), RunID: doc.RunID, Strategy: doc.Strategy,
129				State: doc.State, ModTime: info.ModTime(),
130			}
131			for _, t := range doc.Targets {
132				s.Targets = append(s.Targets, t.Name)
133				s.Levels = max(s.Levels, len(t.Levels))
134			}
135			out = append(out, s)
136		}
137		// Newest first: the history view leads with the latest run.
138		sort.Slice(out, func(i, j int) bool { return out[i].ModTime.After(out[j].ModTime) })
139		return out, nil
140	}
141	
142	// Load reads one doc and normalizes legacy CLI docs into the Targets shape.
143	func Load(dir, file string) (Doc, error) {
144		if !validFile.MatchString(file) {
145			return Doc{}, fmt.Errorf("invalid result filename %q", file)
146		}
147		b, err := os.ReadFile(filepath.Join(dir, file))
148		if errors.Is(err, os.ErrNotExist) {
149			return Doc{}, ErrNotFound
150		}
151		if err != nil {
152			return Doc{}, err
153		}
154		var doc Doc
155		if err := json.Unmarshal(b, &doc); err != nil {
156			return Doc{}, fmt.Errorf("parse %s: %w", file, err)
157		}
158		if doc.Format == 0 && len(doc.Targets) == 0 {
159			// Legacy CLI doc: present it as one pseudo-target named by its label.
160			doc.Targets = []TargetResult{{Name: doc.Target, Label: doc.Target, Levels: doc.Levels}}
161			doc.State = "done"
162		}
163		doc.Target, doc.Levels = "", nil // consumers only see the normalized shape
164		return doc, nil
165	}
