440	// persistResults writes the run's format-2 result doc and returns its bare
441	// filename ("" on failure — the run still finishes; persistence is
442	// best-effort).
443	func (r *Run) persistResults(dir string) string {
444		r.mu.Lock()
445		doc := results.Doc{
446			Format:   2,
447			RunID:    r.ID,
448			Strategy: r.workload.Strategy,
449			Duration: r.bw.Duration.String(),
450			Warmup:   r.bw.Warmup.String(),
451			Commit:   r.bw.CommitDesc(),
452			State:    r.state,
453		}
454		for _, t := range r.targets {
455			doc.Targets = append(doc.Targets, results.TargetResult{
456				Name: t.name, Label: t.label, Error: t.fatalErr,
457				Levels: slices.Clone(t.results), Series: slices.Clone(t.series),
458			})
459		}
460		r.mu.Unlock()
461	
462		file := "forgemark-" + r.ID + ".json"
463		if err := results.Write(dir, file, doc); err != nil {
464			r.log.emit("target_error", map[string]any{
465				"target": -1, "level_index": -1, "fatal": false,
466				"message": "persist results: " + err.Error(),
467			})
468			return ""
469		}
470		return file
471	}
472	
473	func (r *Run) emitBucket() {
474		r.mu.Lock()
475		li, c := r.levelIdx, r.levelConc
476		alive := make([]*targetState, 0, len(r.targets))
477		for _, t := range r.targets {
478			if !t.dead {
479				alive = append(alive, t)
480			}
481		}
482		r.mu.Unlock()
483		if len(alive) == 0 {
484			return
485		}
486		now := time.Now().Unix()
487		stats := make(map[string]BucketStats, len(alive))
488		for _, t := range alive {
489			st := t.col.snapshot()
490			stats[strconv.Itoa(t.id)] = st
491			r.mu.Lock()
492			if len(t.series) < maxBufferedEvents {
493				t.series = append(t.series, results.SeriesPoint{
494					T: now, Level: li, OK: st.OK, CAS: st.CAS, Err: st.Err,
495					P50: st.P50, P95: st.P95, P99: st.P99,
496				})
497			}
498			r.mu.Unlock()
499		}
500		r.log.emit("bucket", map[string]any{
501			"level_index": li, "concurrency": c, "t": now, "targets": stats,
502		})
503	}
504	
505	func (r *Run) markDead(t *targetState, levelIdx int, err error) {
506		r.mu.Lock()
507		t.dead = true
508		t.fatalErr = err.Error()
509		r.mu.Unlock()
510		r.log.emit("target_error", map[string]any{
511			"target": t.id, "level_index": levelIdx, "message": err.Error(), "fatal": true,
512		})
513	}
514	
515	// aliveTargets returns the targets still participating, or nil when none are.
516	func (r *Run) aliveTargets() []*targetState {
517		r.mu.Lock()
518		defer r.mu.Unlock()
519		var out []*targetState
520		for _, t := range r.targets {
521			if !t.dead {
522				out = append(out, t)
523			}
524		}
525		return out
526	}
